package com.yeyamo_mobile.api.feed_service.interfaces.rest;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;import com.yeyamo_mobile.api.feed_service.application.*;import io.swagger.v3.oas.annotations.*;import io.swagger.v3.oas.annotations.security.SecurityRequirement;import io.swagger.v3.oas.annotations.tags.Tag;import jakarta.validation.constraints.*;
@RestController@RequestMapping("/api/v1/feed")@Tag(name="Personalized feed")public class FeedController{private final FeedQueryService service;public FeedController(FeedQueryService s){service=s;}@GetMapping@Operation(summary="Get ranked personalized feed",security=@SecurityRequirement(name="bearerAuth"))public FeedPage feed(@RequestParam(defaultValue="0")@Min(0)int page,@RequestParam(defaultValue="20")@Min(1)@Max(50)int size,Authentication auth){return service.feed(auth.getName(),page,size);}}
